// Raw argv runner: full control over argv, captures rc/stdout/stderr as Buffers+strings.
import { execFile, execFileSync } from 'node:child_process';
export const EXE = '/workspace/dataset/test3_executable';

export function raw(argv, opts = {}) {
  try {
    const out = execFileSync(EXE, argv, { maxBuffer: 1 << 26, ...opts });
    return { rc: 0, out: out.toString('utf8'), err: '', outBuf: out, errBuf: Buffer.alloc(0) };
  } catch (e) {
    const o = e.stdout ?? Buffer.alloc(0), r = e.stderr ?? Buffer.alloc(0);
    return { rc: e.status ?? (e.code ?? 1), out: o.toString('utf8'), err: r.toString('utf8'), outBuf: o, errBuf: r };
  }
}

export async function rawMany(argvs, conc = 48) {
  const res = new Array(argvs.length);
  let next = 0;
  const worker = async () => {
    for (;;) {
      const i = next++;
      if (i >= argvs.length) return;
      res[i] = await new Promise(rs => execFile(EXE, argvs[i], { maxBuffer: 1 << 26, encoding: 'buffer' },
        (e, so, se) => rs({
          rc: e ? (typeof e.code === 'number' ? e.code : 1) : 0,
          out: so.toString('utf8'), err: se.toString('utf8'), outBuf: so, errBuf: se,
        })));
    }
  };
  await Promise.all(Array.from({ length: Math.min(conc, argvs.length) }, worker));
  return res;
}
export const J = s => JSON.stringify(s);

